/**
 * Regenerate the .js copies of the JSON config files.
 *
 *   config/language-mixes.json        -> config/language-mixes-all.js
 *                                       public/config/language-mixes-all.js
 *   config/language-mixer-map.json    -> config/language-mixer-map.js
 *                                       public/config/language-mixer-map.js
 *
 * Why this exists
 *
 * Both generated files carry a header crediting
 * tools/regenerate-js-from-json.js, which is not in the repository. Two copies
 * of each have to stay byte-identical, and M001 in the namebase gate fails the
 * build when they drift, so the regeneration has been done by hand at least
 * twice. This is that script.
 *
 * Usage:  node tools/regenerate-js-from-json.js [--check]
 *
 *   --check  verify the generated files match the JSON; exit 1 if not.
 *            Use in CI or before committing a hand edit to a JSON source.
 *
 * Formatting is fixed rather than derived: CRLF line endings, two-space
 * indentation inside the object literal, and arrays expanded one item per line
 * to match what is already checked in. A compact ["extinct"] would be a
 * gratuitous diff across thousands of lines.
 */
"use strict";

const fs = require("fs");
const path = require("path");

const root = path.resolve(__dirname, "..");
const check = process.argv.includes("--check");

/**
 * Render a value the way the generated files do: JSON, arrays expanded.
 *
 * Arrays are expanded one item per line to match what is checked in - a compact
 * ["extinct"] would be a gratuitous diff across thousands of lines.
 */
function render(value, indent, eol) {
  if (Array.isArray(value)) {
    // An empty array stays on one line. Expanding it to three would be a
    // gratuitous diff on the ~25 rows that have no bases.
    if (value.length === 0) return "[]";
    return `[${eol}${value.map(v => `${indent}  ${JSON.stringify(v)}`).join(`,${eol}`)}${eol}${indent}]`;
  }
  return JSON.stringify(value);
}

/**
 * Wrap an array in the shape the given target expects.
 *
 * language-mixes-all.js assigns to globalThis inside an IIFE; the mixer map
 * assigns to globalThis at top level. Both are plain object literals after the
 * assignment, so only the wrapper differs.
 *
 * The line ending is read from the file being replaced rather than assumed.
 * The two targets are not consistent - language-mixes-all.js is LF and
 * language-mixer-map.js is CRLF - and a generator that rewrote every line of
 * one of them would produce a diff of the entire file, which defeats the point.
 */
function build(values, { iife, indent, eol }) {
  const body = values
    .map(entry => {
      const keys = Object.keys(entry);
      // Each line carries its own trailing comma except the last, so the join
      // is a bare line ending. Joining with "," as well is what produced the
      // doubled commas this file once had.
      const lines = keys.map((k, i) => `${indent}  ${JSON.stringify(k)}: ${render(entry[k], indent + "  ", eol)}${i === keys.length - 1 ? "" : ","}`);
      return `${indent}{${eol}${lines.join(eol)}${eol}${indent}}`;
    })
    .join(`,${eol}`);
  return iife
    ? `"use strict";${eol}${eol}` +
      `// Auto-generated by tools/regenerate-js-from-json.js from config/language-mixes.json.${eol}` +
      `// Edit the JSON source and rerun this script if you change the catalog.${eol}` +
      `(function(){${eol}  globalThis.languageMixerCatalog = [${eol}${body}${eol}  ];${eol}})();${eol}`
    : `globalThis.languageMixerMap = [${eol}${body}${eol}];${eol}`;
}

const TARGETS = [
  {
    source: "config/language-mixes.json",
    outputs: ["config/language-mixes-all.js", "public/config/language-mixes-all.js"],
    iife: true,
    indent: "    "
  },
  {
    source: "config/language-mixer-map.json",
    outputs: ["config/language-mixer-map.js", "public/config/language-mixer-map.js"],
    iife: false,
    indent: "  "
  }
];

let drift = 0;
for (const t of TARGETS) {
  const src = path.join(root, t.source);
  if (!fs.existsSync(src)) {
    console.log(`SKIP  ${t.source} (not present)`);
    continue;
  }
  const values = JSON.parse(fs.readFileSync(src, "utf8"));
  if (!Array.isArray(values)) {
    console.error(`ERROR ${t.source} is not an array`);
    process.exitCode = 1;
    continue;
  }
  // Take the line ending from the file already on disk so the diff stays to
  // the lines that actually changed. The two targets differ and are not
  // normalised against each other.
  const existing = fs.existsSync(path.join(root, t.outputs[0]))
    ? fs.readFileSync(path.join(root, t.outputs[0]), "utf8")
    : "\n";
  const eol = existing.includes("\r\n") ? "\r\n" : "\n";
  const out = build(values, { ...t, eol });
  for (const rel of t.outputs) {
    const dest = path.join(root, rel);
    const current = fs.existsSync(dest) ? fs.readFileSync(dest, "utf8") : null;
    if (check) {
      if (current === out) {
        console.log(`OK    ${rel}`);
      } else {
        drift++;
        console.log(`DRIFT ${rel} differs from ${t.source}`);
      }
    } else {
      fs.writeFileSync(dest, out, "utf8");
      console.log(`WROTE ${rel}  (${values.length} entries)`);
    }
  }
}

if (check) {
  if (drift) {
    console.log(`\n${drift} generated file(s) out of date. Run: node tools/regenerate-js-from-json.js`);
    process.exitCode = 1;
  } else {
    console.log("\nAll generated files match their JSON sources.");
  }
}
